import{_ as p,a0 as s,w as d,s as a,ao as f,I as o,x as n,a1 as r,A as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const h=JSON.parse('{"title":"使用 Find 命令來幫你找到那些需要清理的文件 | LCTT x X-CMD","titleTemplate":false,"description":"使用 Find 命令來幫你找到那些需要清理的文件 | LCTT (201508) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"使用 Find 命令來幫你找到那些需要清理的文件 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"使用 Find 命令來幫你找到那些需要清理的文件 | LCTT (201508) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201508/20150803 Handy commands for profiling your Unix file systems","title":"使用 Find 命令來幫你找到那些需要清理的文件","tag":"201508","desc":""},"relativePath":"201508/20150803 Handy commands for profiling your Unix file systems.md","filePath":"[post].md"}'),l={name:"201508/20150803 Handy commands for profiling your Unix file systems.md"};function m(u,t,y,g,T,x){const e=s("Link");return d(),a("div",null,[t[13]||(t[13]=f(`<h1 id="使用-find-命令來幫你找到那些需要清理的文件" tabindex="-1">使用 Find 命令來幫你找到那些需要清理的文件 <a class="header-anchor" href="#使用-find-命令來幫你找到那些需要清理的文件" aria-label="Permalink to “使用 Find 命令來幫你找到那些需要清理的文件”">​</a></h1><p><img src="http://images.techhive.com/images/article/2015/07/file-profile-100597239-primary.idge.png" alt="Credit: Sandra H-S"></p><p><em>Credit: Sandra H-S</em></p><p>有一個問題幾乎困擾着所有的文件系統 -- 包括 Unix 和其他的 -- 那就是文件的不斷積累。幾乎沒有人願意花時間清理掉他們不再使用的文件和整理文件系統，結果，文件變得很混亂，很難找到有用的東西，要使它們運行良好、維護備份、易於管理，這將是一種持久的挑戰。</p><p>我見過的一種解決問題的方法是建議使用者將所有的數據碎屑創建一個文件集合的總結報告或&quot;概況&quot;，來報告諸如所有的文件數量；最老的，最新的，最大的文件；並統計誰擁有這些文件等數據。如果有人看到五年前的一個包含五十萬個文件的文件夾，他們可能會去刪除哪些文件 -- 或者，至少會歸檔和壓縮。主要問題是太大的文件夾會使人擔心誤刪一些重要的東西。如果有一個描述文件夾的方法能幫助顯示文件的性質，那麼你就可以去清理它了。</p><p>當我準備做 Unix 文件系統的總結報告時，幾個有用的 Unix 命令能提供一些非常有用的統計信息。要計算目錄中的文件數，你可以使用這樣一個 find 命令。</p><pre><code>$ find . -type f | wc -l
187534
</code></pre><p>雖然查找最老的和最新的文件是比較複雜，但還是相當方便的。在下面的命令，我們使用 find 命令再次查找文件，以文件時間排序並按年-月-日的格式顯示，在列表頂部的顯然是最老的。</p><p>在第二個命令，我們做同樣的，但打印的是最後一行，這是最新的。</p><pre><code>$ find -type f -printf &#39;%T+ %p\\n&#39; | sort | head -n 1
2006-02-03+02:40:33 ./skel/.xemacs/init.el
$ find -type f -printf &#39;%T+ %p\\n&#39; | sort | tail -n 1
2015-07-19+14:20:16 ./.bash_history
</code></pre><p>printf 命令輸出 ％T（文件日期和時間）和 ％P（帶路徑的文件名）參數。</p><p>如果我們在查找家目錄時，無疑會發現，history 文件（如 .bash_history）是最新的，這並沒有什麼用。你可以通過 &quot;un-grepping&quot; 來忽略這些文件，也可以忽略以.開頭的文件，如下圖所示的。</p><pre><code>$ find -type f -printf &#39;%T+ %p\\n&#39; | grep -v &quot;\\./\\.&quot; | sort | tail -n 1
2015-07-19+13:02:12 ./isPrime
</code></pre><p>尋找最大的文件使用 ％s（大小）參數，包括文件名（％f），因為這就是我們想要在報告中顯示的。</p><pre><code>$ find -type f -printf &#39;%s %f \\n&#39; | sort -n | uniq | tail -1
20183040 project.org.tar
</code></pre><p>統計文件的所有者，使用％u（所有者）</p><pre><code>$ find -type f -printf &#39;%u \\n&#39; | grep -v &quot;\\./\\.&quot; | sort | uniq -c
   180034 shs
     7500 jdoe
</code></pre><p>如果文件系統能記錄上次的訪問日期，也將是非常有用的，可以用來看該文件有沒有被訪問過，比方説，兩年之內沒訪問過。這將使你能明確分辨這些文件的價值。這個最後訪問（％a）參數這樣使用：</p><pre><code>$ find -type f -printf &#39;%a+ %p\\n&#39; | sort | head -n 1
Fri Dec 15 03:00:30 2006+ ./statreport
</code></pre><p>當然，如果大多數最近​​訪問的文件也是在很久之前的，這看起來你需要處理更多文件了。</p><pre><code>$ find -type f -printf &#39;%a+ %p\\n&#39; | sort | tail -n 1
Wed Nov 26 03:00:27 2007+ ./my-notes
</code></pre><p>要想層次分明，可以為一個文件系統或大目錄創建一個總結報告，顯示這些文件的日期範圍、最大的文件、文件所有者們、最老的文件和最新訪問時間，可以幫助文件擁有者判斷當前有哪些文件夾是重要的哪些該清理了。</p><hr>`,23)),o("p",null,[t[1]||(t[1]=n("via: ",-1)),r(e,{href:"http://www.itworld.com/article/2949898/linux/profiling-your-file-systems.html"},{default:i(()=>[...t[0]||(t[0]=[n("http://www.itworld.com/article/2949898/linux/profiling-your-file-systems.html",-1)])]),_:1})]),o("p",null,[t[5]||(t[5]=n("作者：",-1)),r(e,{href:"http://www.itworld.com/author/Sandra-Henry_Stocker/"},{default:i(()=>[...t[2]||(t[2]=[n("Sandra Henry-Stocker",-1)])]),_:1}),t[6]||(t[6]=n(" 譯者：",-1)),r(e,{href:"https://github.com/strugglingyouth"},{default:i(()=>[...t[3]||(t[3]=[n("strugglingyouth",-1)])]),_:1}),t[7]||(t[7]=n(" 校對：",-1)),r(e,{href:"https://github.com/wxy"},{default:i(()=>[...t[4]||(t[4]=[n("wxy",-1)])]),_:1})]),o("p",null,[t[10]||(t[10]=n("本文由 ",-1)),r(e,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...t[8]||(t[8]=[n("LCTT",-1)])]),_:1}),t[11]||(t[11]=n(" 原創翻譯，",-1)),r(e,{href:"https://linux.cn/"},{default:i(()=>[...t[9]||(t[9]=[n("Linux中國",-1)])]),_:1}),t[12]||(t[12]=n(" 榮譽推出",-1))])])}const _=p(l,[["render",m]]);export{h as __pageData,_ as default};
